const USER_HP = require('./images/user-hp.png');

const SCREEN_WIDTH = Dimensions.get('window').width;
const SCREEN_HEIGHT = Dimensions.get('window').height;

const brandColor = '#744BAC';
const MAX_LENGTH_CODE = 6;
const MAX_LENGTH_NUMBER = 20;

export default class Signup extends Component {
  constructor(props) {
    super(props);

    this.state = {
      isReady: true,
      isLoading: false,
      enterCode: false,
      selectedType: null,
      fontLoaded: false,
      name: '',
      phone: '',
      phoneIN: '',
      phoneLogin: '',
      phoneValid: true,
      username:'',
      usernameValid: true,
      isModalVisible: false,
      verificationId: '',
      code: '',
      OTP1:'',
      OTP2:'',
      OTP3:'',
      OTP4:'',
      OTP5:'',
      OTP6:'',
    };

    this.setSelectedType = this.setSelectedType.bind(this);
    this.validatePhone = this.validatePhone.bind(this);
    this.signon = this.signon.bind(this);
    this.storeData = this.storeData.bind(this);
    this.retrieveData = this.retrieveData.bind(this);
    this._verifyCode = this._verifyCode.bind(this);
    this.auth = this.auth.bind(this);
  }


  async auth() {
    LayoutAnimation.easeInEaseOut();
    this.setState({isReady: false});
    const phoneValid = await this.validatePhone();
    if (phoneValid && this.state.phoneIN!='') {
      firebase.auth()
      .verifyPhoneNumber(this.state.phoneIN)
      .on('state_changed', (phoneAuthSnapshot) => {
        switch (phoneAuthSnapshot.state) {
          // ------------------------
          //  IOS AND ANDROID EVENTS
          // ------------------------
          case firebase.auth.PhoneAuthState.CODE_SENT: // or 'sent'
            console.log('code sent');
            this.setState({verificationId: phoneAuthSnapshot.verificationId});
            this.setState({ isModalVisible: true });
            break;

          case firebase.auth.PhoneAuthState.ERROR: // or 'error'
            this.setState({isReady: true});
            console.log('verification error');
            
            break;

          // ---------------------
          // ANDROID ONLY EVENTS
          // ---------------------
          case firebase.auth.PhoneAuthState.AUTO_VERIFY_TIMEOUT: // or 'timeout'
            console.log('auto verify on android timed out');
            
            break;
          case firebase.auth.PhoneAuthState.AUTO_VERIFIED:
            ToastAndroid.show('Auto Verified', ToastAndroid.SHORT);
            console.log('auto verified on android');
            
            // Example usage if handling here and not in optionalCompleteCb:
            const { verificationId, code } = phoneAuthSnapshot;
            const credential = firebase.auth.PhoneAuthProvider.credential(verificationId, code);
            this.signon(credential);

            
            // firebase.auth().currentUser.linkWithCredential(credential);
            // etc ...
            break;
        }
      }, (error) => {
        // optionalErrorCb would be same logic as the ERROR case above,  if you've already handed
        // the ERROR case in the above observer then there's no need to handle it here
        console.log('error');
        // verificationId is attached to error if required
        console.log(error.verificationId);
      }, (phoneAuthSnapshot) => {
        // optionalCompleteCb would be same logic as the AUTO_VERIFIED/CODE_SENT switch cases above
        // depending on the platform. If you've already handled those cases in the observer then
        // there's absolutely no need to handle it here.

        // Platform specific logic:
        // - if this is on IOS then phoneAuthSnapshot.code will always be null
        // - if ANDROID auto verified the sms code then phoneAuthSnapshot.code will contain the verified sms code
        //   and there'd be no need to ask for user input of the code - proceed to credential creating logic
        // - if ANDROID auto verify timed out then phoneAuthSnapshot.code would be null, just like ios, you'd
        //   continue with user input logic.
        console.log('phoneAuthSnapshot');
  });
    }
  }

  signon(credential){
    firebase.auth().signInWithCredential(credential).then((result) => {
                        
                        this.setState({ isModalVisible: false });
                        result.user.getIdToken().then(function(idToken) {
                          userIdToken = idToken;
                          console.log("hsabhjsa: "+idToken);
                          axios.defaults.headers.common['Authorization'] = idToken;
                          axios.defaults.headers.post['Content-Type'] = 'application/json';
                          
                          this.storeData(userIdToken);
                          this.retrieveData();

                          if (result.additionalUserInfo.isNewUser) {
                              //this.props.navigation.navigate('Login', {}, NavigationActions.navigate({ routeName: 'Home' }));
                              this.props.navigation.navigate("UserDetails");
                            }
                          else { 
                            axios.get('http://classcast-198812.appspot.com/graphql?query=query {getUserInfo(username:"'+ result.user.phoneNumber.slice(3,13)+'"){username}}')
                            .then(res=> {
                              if(res.data.data.getUserInfo == null) {
                                this.props.navigation.navigate("UserDetails");
                              }
                              else {
                                ToastAndroid.show('Please wait', ToastAndroid.SHORT);
                                axios.get(`https://classcast-198812.appspot.com/deviceid/get_device_id`)
                                .then(response => {
                                  if(DeviceInfo.getUniqueID() == response.data) {
                                    this.setState({isReady: true});
                                    this.props.navigation.navigate("Home");
                                  }
                                  else {
                                    this.setState({isReady: true});
                                    ToastAndroid.show('Sorry, another account from you is already signed. Please contact your teacher', ToastAndroid.SHORT);
                                  }
                                })
                                .catch(err =>{
                                  console.log("xsjkbsacjb: "+err);
                                  this.setState({isReady: true});
                                  //ToastAndroid.show('Something went wrong', ToastAndroid.SHORT);
                                })
                              }
                            })
                          }
                          
                         }.bind(this));

                          }, (error) => {
                            console.log("singon error");
                            this.setState({isModalVisible: false});
                            this.setState({isReady: true});
                            console.log("xsjkbsacjbb: "+error);
                            //ToastAndroid.show('Something went wrong', ToastAndroid.SHORT);
                          });

  }

  async storeData (data) {
    const {phone} = this.state;
    try{ await AsyncStorage.setItem("Token", data);
         await AsyncStorage.setItem("Phone", phone);
        }
    catch (error) {console.log("error");}
  }

  async retrieveData () { 
    const token =  await AsyncStorage.getItem("Token");
  }


  validatePhone() {
    const { phone, phoneIN } = this.state;
    const phoneValid = phone.length=10;
    LayoutAnimation.easeInEaseOut();
    this.setState({phoneIN: '+'+91 + ''+ phone});
    this.setState({ phoneValid });
    phoneValid || this.phoneInput.shake();
    return phoneValid;
  }


  setSelectedType = selectedType =>
    LayoutAnimation.easeInEaseOut() || this.setState({ selectedType });

  _toggleModal = () =>
    this.setState({ isModalVisible: !this.state.isModalVisible });

  _verifyCode = (val) => {
    //this.setState({code: val});
    const credential = firebase.auth.PhoneAuthProvider.credential(this.state.verificationId, val+'');
    this.signon(credential);
  }

  _onChangeText = (val) => {
    if (val.length === 6){
      this._verifyCode(val);
    }
      //this._verifyCode();
  }

  componentWillMount() {
    Orientation.lockToPortrait();
    const initial = Orientation.getInitialOrientation();
  }

  componentDidMount() {
    Orientation.lockToPortrait();
  }

  render() {
    const {
      isLoading,
      selectedType,
      phone,
      phoneLogin,
      phoneValid,
      username,
      usernameValid,
      isModalVisible,
      OTP1,
      OTP2,
      OTP3,
      OTP4,
      OTP5,
      OTP6,
      phoneIN,
      verificationId
    } = this.state;

    let textStyle = this.state.enterCode ? {
      height: .2 * SCREEN_HEIGHT,
      textAlign: 'center',
      fontSize: 40,
      fontWeight: 'bold',
      fontFamily: 'Courier'
    } : {};

    return (
      <ScrollView style={{backgroundColor: '#fef6e8'}}
      contentContainerStyle ={{backgroundColor: '#fef6e8'}}
        scrollEnabled={true}
        keyboardShouldPersistTaps="handled">
          <View style={{ flex: 1, backgroundColor: '#fef6e9', position: 'absolute', height: SCREEN_HEIGHT, width: SCREEN_WIDTH }}>
          <Image
            style={{height: SCREEN_HEIGHT, width: SCREEN_WIDTH, position: 'absolute', marginTop: 0}}
            resizeMode={'stretch'}
            source={{uri: 'data:image/png;base64,'}}
          />
            <Modal isVisible={this.state.isModalVisible} style={styles.bottomModal}>
              <View style={styles.modalContent}>
                <Text style={{fontSize:20}}>Enter OTP</Text>
                <View style={{height:50, width:'100%', marginLeft:10, marginRight:10, alignItems:'center', justifyContent: 'center', marginTop: 10}}>
                <View style={{flexDirection:'row', flex:1}}>
                  <View style={{height: .07 * SCREEN_HEIGHT, width:'40%', margin:5}}>
                  <TextInput
                    ref={'textInput'}
                    name={'OTP'}
                    type={'TextInput'}
                    underlineColorAndroid={'transparent'}
                    autoCapitalize={'none'}
                    autoCorrect={false}
                    onChangeText={this._onChangeText}
                    placeholder={this.state.enterCode ? '_ _ _ _ _ _' : 'OTP'}
                    keyboardType={'numeric'}
                    style={[ styles.textInput, textStyle, { textAlign: 'center', borderColor: 'purple', borderWidth: 1, borderRadius: 15, width: '100%', padding: 6, justifyContent: 'center', alignItems: 'center'} ]}
                    //style={{height: 40, borderColor: 'purple', borderWidth: 1, borderRadius: 20}}
                    returnKeyType='go'
                    autoFocus
                    placeholderTextColor={brandColor}
                    selectionColor={brandColor}
                    maxLength={6}
                    onSubmitEditing={this._verifyCode} />
                  </View>
                  </View>
                  </View>
                <TouchableOpacity onPress={this._verifyCode}>
                  <View style={styles.nextPage}>
                    <Image
                      style={styles.nextPageIcon}
                      resizeMode={'contain'}
                      source={{uri: 'data:image/png;base64,'}}
                    />
                  </View>
                </TouchableOpacity>
              </View>
              
            </Modal>
          </View>
          { !this.state.isReady && !this.state.isModalVisible&&
            <View style={{height: 20 * vh, width: '100%', borderRadius: 1.5 * vw, alignItems: 'center', justifyContent: 'center', marginTop: 20 * vh, position: 'absolute', paddingTop: .2 * SCREEN_HEIGHT}}>
              <MaterialIndicator color='white'/>
              <Text style={[styles.signUpText, {fontSize: 20, marginTop: .03 * SCREEN_HEIGHT}]}> Loading...</Text>
              
            </View>
          }
          { 
            <Text style={styles.signUpText}>{this.state.isReady ? 'Start your journey': ''}</Text>
          }
          <Text style={styles.whoAreYouText}>What is you dial number?</Text>
          
            <FormInput
              refInput={input => (this.phoneInput = input)}
              icon="phone"
              value={phone}
              
              onChangeText={phone => this.setState({ phone })}
              placeholder="Enter your 10 digit Phone No."
              keyboardType='numeric'
              returnKeyType="next"
              errorMessage={
                phoneValid ? null : 'Please enter a valid phone address'
              }
              onSubmitEditing={() => {
                this.validatePhone();
              }}
            />
            
           { this.state.isReady &&
            <Button
              title="Continue"
              containerStyle={{ flex: -1 }}
              buttonStyle={styles.signUpButton}
              titleStyle={styles.signUpButtonText}
              onPress={
                this.auth
              }
            />
            }
      </ScrollView>
    );
  }
}


export const FormInput = props => {
  const { icon, refInput, ...otherProps } = props;
  return (
    <Input
      {...otherProps}
      ref={refInput}
      inputContainerStyle={styles.inputContainer}
      leftIcon={<Icon name={icon} color="#7384B4" size={.06 * SCREEN_WIDTH} />}
      inputStyle={styles.inputStyle}
      autoFocus={true}
      autoCapitalize="none"
      keyboardAppearance="dark"
      errorStyle={styles.errorInputStyle}
      autoCorrect={true}
      blurOnSubmit={true}
      placeholderTextColor="#7384B4"
    />
  );
};

export const OTPInput = props => {
  const { icon, refInput, ...otherProps } = props;
  return (
    <Input
      {...otherProps}
      ref={refInput}
      inputContainerStyle={styles.OTPinputContainer}
      leftIcon={<Icon name={icon} color="#7384B4" size={18} />}
      inputStyle={styles.OTPinputStyle}
      autoFocus={false}
      autoCapitalize="none"
      keyboardAppearance="dark"
      maxLength={1}
      errorStyle={styles.errorInputStyle}
      autoCorrect={false}
      blurOnSubmit={true}
      placeholderTextColor="#7384B4"
    />
  );
};

